package main

import (
	"slices"

	"github.com/corentings/chess/v2"
)

const quietHistoryLimit = 16384

// Cutoff-ordering hints are private to one search, shared across its iterative
// passes. They never supply scores or alter repetition history or legal moves.
type quietHistory [2][64][64]int16

func historySide(side chess.Color) int {
	if side == chess.Black {
		return 1
	}
	return 0
}

func (w *searcher) rememberQuietHistory(side chess.Color, move chess.Move, depth int) {
	if depth <= 0 || !isQuietMove(move) {
		return
	}
	if w.quietHistory == nil {
		w.quietHistory = new(quietHistory)
	}
	depth = min(depth, maxSearchDepth)
	bonus := min(depth*depth, 2048)
	entry := &w.quietHistory[historySide(side)][move.S1()][move.S2()]
	value := int(*entry)
	*entry = int16(value + bonus - value*bonus/quietHistoryLimit)
}

func (w *searcher) orderQuietHistory(moves []chess.Move, side chess.Color, ply int) {
	if w.quietHistory == nil {
		return
	}
	start := 0
	for start < len(moves) && !isQuietMove(moves[start]) {
		start++
	}
	quiet := moves[start:]
	if len(quiet) < 2 {
		return
	}
	ranks := w.rankBuffers[ply][:0]
	ordered := true
	index := historySide(side)
	for i := range quiet {
		m := &quiet[i]
		value := int(w.quietHistory[index][m.S1()][m.S2()])
		if i > 0 && value > ranks[i-1].priority {
			ordered = false
		}
		ranks = append(ranks, moveRank{index: i, priority: value})
	}
	w.rankBuffers[ply] = ranks
	if !ordered {
		slices.SortStableFunc(ranks, func(a, b moveRank) int { return b.priority - a.priority })
		applyMoveOrder(quiet, ranks)
	}
}

