package main

import (
	"context"
	"reflect"
	"slices"
	"testing"

	"github.com/corentings/chess/v2"
)

func TestQuietHistoryBoundsEligibilityAndIsolation(t *testing.T) {
	p := chess.StartingPosition()
	m := p.ValidMoves()[0]
	w := searcher{}
	w.rememberQuietHistory(chess.White, m, 0)
	if w.quietHistory != nil {
		t.Fatal("zero depth allocated history")
	}
	w.rememberQuietHistory(chess.White, m, 3)
	if got := w.quietHistory[0][m.S1()][m.S2()]; got != 9 {
		t.Fatal("initial depth bonus", got)
	}
	for i := 0; i < 20000; i++ {
		w.rememberQuietHistory(chess.White, m, 64)
	}
	if got := w.quietHistory[0][m.S1()][m.S2()]; got < 0 || got > quietHistoryLimit {
		t.Fatal("history escaped bound", got)
	}
	if w.quietHistory[1][m.S1()][m.S2()] != 0 {
		t.Fatal("side history leaked")
	}
	fresh := searcher{}
	if fresh.quietHistory != nil {
		t.Fatal("worker history shared")
	}
	tactical := evalFEN(t, "r6k/1P6/8/8/8/8/8/7K w - - 0 1")
	for _, m := range tactical.ValidMoves() {
		if !isQuietMove(m) {
			q := searcher{}
			q.rememberQuietHistory(chess.White, m, 6)
			if q.quietHistory != nil {
				t.Fatal("tactical move received quiet bonus", m)
			}
		}
	}
	ep := evalFEN(t, "4k3/8/8/3pP3/8/8/8/4K3 w - d6 0 1")
	for _, m := range ep.ValidMoves() {
		if m.HasTag(chess.EnPassant) {
			q := searcher{}
			q.rememberQuietHistory(chess.White, m, 4)
			if q.quietHistory != nil {
				t.Fatal("EP received quiet bonus")
			}
		}
	}
}

func TestQuietHistoryStableOrderingAndOwnership(t *testing.T) {
	for _, fen := range []string{chess.StartingPosition().String(), "r6k/1P6/8/8/8/8/6N1/7K w - - 0 1", queenRaidPosition} {
		p := evalFEN(t, fen)
		cached := slices.Clone(p.ValidMoves())
		w := searcher{}
		moves := w.searchMoves(p, 0, false)
		original := slices.Clone(moves)
		w.orderQuietHistory(moves, p.Turn(), 0)
		if !reflect.DeepEqual(moves, original) {
			t.Fatal("nil history changed stable order")
		}
		w.quietHistory = new(quietHistory)
		for i, m := range moves {
			if isQuietMove(m) {
				w.quietHistory[historySide(p.Turn())][m.S1()][m.S2()] = int16(i % 4)
			}
		}
		want := slices.Clone(moves)
		slices.SortStableFunc(want, func(a, b chess.Move) int {
			aq, bq := isQuietMove(a), isQuietMove(b)
			if aq && !bq {
				return 1
			}
			if !aq && bq {
				return -1
			}
			if !aq {
				return 0
			}
			s := historySide(p.Turn())
			return int(w.quietHistory[s][b.S1()][b.S2()]) - int(w.quietHistory[s][a.S1()][a.S2()])
		})
		w.orderQuietHistory(moves, p.Turn(), 0)
		if !reflect.DeepEqual(moves, want) {
			t.Fatal("history changed moves/tags or stable tactical/tied order")
		}
		saved := slices.Clone(moves)
		for i := 0; i < 4; i++ {
			childMoves := w.searchMoves(chess.StartingPosition(), 30, false)
			w.orderQuietHistory(childMoves, chess.White, 30)
		}
		if !reflect.DeepEqual(moves, saved) {
			t.Fatal("child ranks overwrote parent")
		}
		if !reflect.DeepEqual(p.ValidMoves(), cached) {
			t.Fatal("position cache mutated")
		}
	}
}

func TestQuietHistoryKillerAndTablePrecedence(t *testing.T) {
	p := chess.StartingPosition()
	w := searcher{killers: new(killerTable)}
	moves := w.searchMoves(p, 0, false)
	original := slices.Clone(moves)
	w.rememberQuietHistory(chess.White, original[3], 7)
	w.rememberQuietHistory(chess.White, original[2], 3)
	w.orderQuietHistory(moves, chess.White, 0)
	if moves[0].String() != original[3].String() {
		t.Fatal("history hint not used")
	}
	w.killers.remember(0, original[1])
	w.killers.order(moves, 0)
	preferMove(moves, encodeMove(original[0]))
	if moves[0].String() != original[0].String() || moves[1].String() != original[1].String() || moves[2].String() != original[3].String() {
		t.Fatal("TT/killer/history precedence")
	}
	fresh := searcher{}
	reset := fresh.searchMoves(p, 0, false)
	fresh.orderQuietHistory(reset, chess.White, 0)
	if !reflect.DeepEqual(reset, original) {
		t.Fatal("new search retained prior history")
	}
}

func TestQuietHistoryCanceledEntryDoesNotLearn(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	w := searcher{ctx: ctx}
	if _, ok := w.search(chess.StartingPosition(), 4, -searchInfinity, searchInfinity, false); ok || w.quietHistory != nil {
		t.Fatal("canceled entry searched/learned")
	}
}

